341	impl Connection {
342	    /// Register a callback function to be invoked whenever
343	    /// a transaction is committed.
344	    ///
345	    /// The callback returns `true` to rollback.
346	    #[inline]
347	    pub fn commit_hook<F>(&mut self, hook: Option<F>) -> Result<()>
348	    where
349	        F: FnMut() -> bool + Send + 'static,
350	    {
351	        self.db.borrow_mut().commit_hook(hook)
352	    }
353	
354	    /// Register a callback function to be invoked whenever
355	    /// a transaction is rolled back.
356	    #[inline]
357	    pub fn rollback_hook<F>(&mut self, hook: Option<F>) -> Result<()>
358	    where
359	        F: FnMut() + Send + 'static,
360	    {
361	        self.db.borrow_mut().rollback_hook(hook)
362	    }
363	
364	    /// Register a callback function to be invoked whenever
365	    /// a row is updated, inserted or deleted in a rowid table.
366	    ///
367	    /// The callback parameters are:
368	    ///
369	    /// - the type of database update (`SQLITE_INSERT`, `SQLITE_UPDATE` or
370	    ///   `SQLITE_DELETE`),
371	    /// - the name of the database ("main", "temp", ...),
372	    /// - the name of the table that is updated,
373	    /// - the ROWID of the row that is updated.
374	    #[inline]
375	    pub fn update_hook<F>(&mut self, hook: Option<F>) -> Result<()>
376	    where
377	        F: FnMut(Action, &str, &str, i64) + Send + 'static,
378	    {
379	        self.db.borrow_mut().update_hook(hook)
380	    }
381	
382	    /// Register a callback that is invoked each time data is committed to a database in wal mode.
383	    ///
384	    /// A single database handle may have at most a single write-ahead log callback registered at one time.
385	    /// Calling `wal_hook` replaces any previously registered write-ahead log callback.
386	    /// Note that the `sqlite3_wal_autocheckpoint()` interface and the `wal_autocheckpoint` pragma
387	    /// both invoke `sqlite3_wal_hook()` and will overwrite any prior `sqlite3_wal_hook()` settings.
388	    pub fn wal_hook<F>(&mut self, hook: Option<F>) -> Result<()>
389	    where
390	        F: FnMut(&Wal, c_int) -> Result<()> + Send + 'static,
391	    {
392	        unsafe extern "C" fn wal_hook_callback<F>(
393	            client_data: *mut c_void,
394	            db: *mut ffi::sqlite3,
395	            db_name: *const c_char,
396	            pages: c_int,
397	        ) -> c_int
398	        where
399	            F: FnMut(&Wal, c_int) -> Result<()>,
400	        {
401	            unsafe {
402	                let wal = Wal { db, db_name };
403	                catch_unwind(|| {
404	                    let hook_fn: *mut F = client_data.cast::<F>();
405	                    match (*hook_fn)(&wal, pages) {
406	                        Ok(()) => ffi::SQLITE_OK,
407	                        Err(e) => e
408	                            .sqlite_error()
409	                            .map_or(ffi::SQLITE_ERROR, |x| x.extended_code),
410	                    }
411	                })
412	                .unwrap_or_default()
413	            }
414	        }
415	        let x = hook.as_ref().map(|_| wal_hook_callback::<F> as _);
416	        let mut c = self.db.borrow_mut();
417	        c.set_clientdata(c"sqlite3_wal_hook", hook, |db, bh| unsafe {
418	            ffi::sqlite3_wal_hook(db, x, bh);
419	            ffi::SQLITE_OK
420	        })?;
421	        Ok(())
422	    }
423	
424	    /// Register a query progress callback.
425	    ///
426	    /// The parameter `num_ops` is the approximate number of virtual machine
427	    /// instructions that are evaluated between successive invocations of the
428	    /// `handler`. If `num_ops` is less than one then the progress handler
429	    /// is disabled.
430	    ///
431	    /// If the progress callback returns `true`, the operation is interrupted.
432	    pub fn progress_handler<F>(&mut self, num_ops: c_int, handler: Option<F>) -> Result<()>
433	    where
434	        F: FnMut() -> bool + Send + 'static,
435	    {
436	        self.db.borrow_mut().progress_handler(num_ops, handler)
437	    }
438	
439	    /// Register an authorizer callback that's invoked
440	    /// as a statement is being prepared.
441	    #[inline]
442	    pub fn authorizer<F>(&mut self, hook: Option<F>) -> Result<()>
443	    where
444	        F: for<'r> FnMut(AuthContext<'r>) -> Authorization + Send + 'static,
445	    {
446	        self.db.borrow_mut().authorizer(hook)
447	    }
448	}
