450	/// Checkpoint mode
451	#[derive(Clone, Copy)]
452	#[repr(i32)]
453	#[non_exhaustive]
454	pub enum CheckpointMode {
455	    /// Do as much as possible w/o blocking
456	    PASSIVE = ffi::SQLITE_CHECKPOINT_PASSIVE,
457	    /// Wait for writers, then checkpoint
458	    FULL = ffi::SQLITE_CHECKPOINT_FULL,
459	    /// Like FULL but wait for readers
460	    RESTART = ffi::SQLITE_CHECKPOINT_RESTART,
461	    /// Like RESTART but also truncate WAL
462	    TRUNCATE = ffi::SQLITE_CHECKPOINT_TRUNCATE,
463	    /// Do no work at all
464	    #[cfg(feature = "modern_sqlite")] // 3.51.0
465	    NOOP = -1, //ffi::SQLITE_CHECKPOINT_NOOP,
466	}
