506	impl InnerConnection {
507	    /// ```compile_fail
508	    /// use rusqlite::{Connection, Result};
509	    /// fn main() -> Result<()> {
510	    ///     let mut db = Connection::open_in_memory()?;
511	    ///     {
512	    ///         let mut called = std::sync::atomic::AtomicBool::new(false);
513	    ///         db.commit_hook(Some(|| {
514	    ///             called.store(true, std::sync::atomic::Ordering::Relaxed);
515	    ///             true
516	    ///         }));
517	    ///     }
518	    ///     assert!(db
519	    ///         .execute_batch(
520	    ///             "BEGIN;
521	    ///         CREATE TABLE foo (t TEXT);
522	    ///         COMMIT;",
523	    ///         )
524	    ///         .is_err());
525	    ///     Ok(())
526	    /// }
527	    /// ```
528	    fn commit_hook<F>(&mut self, hook: Option<F>) -> Result<()>
529	    where
530	        F: FnMut() -> bool + Send + 'static,
531	    {
532	        unsafe extern "C" fn call_boxed_closure<F>(p_arg: *mut c_void) -> c_int
533	        where
534	            F: FnMut() -> bool,
535	        {
536	            unsafe {
537	                let r = catch_unwind(|| {
538	                    let boxed_hook: *mut F = p_arg.cast::<F>();
539	                    (*boxed_hook)()
540	                });
541	                c_int::from(r.unwrap_or_default())
542	            }
543	        }
544	        let x = hook.as_ref().map(|_| call_boxed_closure::<F> as _);
545	        self.set_clientdata(c"sqlite3_commit_hook", hook, |db, bh| unsafe {
546	            ffi::sqlite3_commit_hook(db, x, bh);
547	            ffi::SQLITE_OK
548	        })?;
549	        Ok(())
550	    }
551	
552	    /// ```compile_fail
553	    /// use rusqlite::{Connection, Result};
554	    /// fn main() -> Result<()> {
555	    ///     let mut db = Connection::open_in_memory()?;
556	    ///     {
557	    ///         let mut called = std::sync::atomic::AtomicBool::new(false);
558	    ///         db.rollback_hook(Some(|| {
559	    ///             called.store(true, std::sync::atomic::Ordering::Relaxed);
560	    ///         }));
561	    ///     }
562	    ///     assert!(db
563	    ///         .execute_batch(
564	    ///             "BEGIN;
565	    ///         CREATE TABLE foo (t TEXT);
566	    ///         ROLLBACK;",
567	    ///         )
568	    ///         .is_err());
569	    ///     Ok(())
570	    /// }
571	    /// ```
572	    fn rollback_hook<F>(&mut self, hook: Option<F>) -> Result<()>
573	    where
574	        F: FnMut() + Send + 'static,
575	    {
576	        unsafe extern "C" fn call_boxed_closure<F>(p_arg: *mut c_void)
577	        where
578	            F: FnMut(),
579	        {
580	            unsafe {
581	                drop(catch_unwind(|| {
582	                    let boxed_hook: *mut F = p_arg.cast::<F>();
583	                    (*boxed_hook)();
584	                }));
585	            }
586	        }
587	
588	        let x = hook.as_ref().map(|_| call_boxed_closure::<F> as _);
589	        self.set_clientdata(c"sqlite3_rollback_hook", hook, |db, bh| unsafe {
590	            ffi::sqlite3_rollback_hook(db, x, bh);
591	            ffi::SQLITE_OK
592	        })?;
593	        Ok(())
594	    }
595	
596	    /// ```compile_fail
597	    /// use rusqlite::{Connection, Result};
598	    /// fn main() -> Result<()> {
599	    ///     let mut db = Connection::open_in_memory()?;
600	    ///     {
601	    ///         let mut called = std::sync::atomic::AtomicBool::new(false);
602	    ///         db.update_hook(Some(|_, _: &str, _: &str, _| {
603	    ///             called.store(true, std::sync::atomic::Ordering::Relaxed);
604	    ///         }));
605	    ///     }
606	    ///     db.execute_batch("CREATE TABLE foo AS SELECT 1 AS bar;")
607	    /// }
608	    /// ```
609	    fn update_hook<F>(&mut self, hook: Option<F>) -> Result<()>
610	    where
611	        F: FnMut(Action, &str, &str, i64) + Send + 'static,
612	    {
613	        unsafe extern "C" fn call_boxed_closure<F>(
614	            p_arg: *mut c_void,
615	            action_code: c_int,
616	            p_db_name: *const c_char,
617	            p_table_name: *const c_char,
618	            row_id: i64,
619	        ) where
620	            F: FnMut(Action, &str, &str, i64),
621	        {
622	            let action = Action::from(action_code);
623	            unsafe {
624	                drop(catch_unwind(|| {
625	                    let boxed_hook: *mut F = p_arg.cast::<F>();
626	                    (*boxed_hook)(
627	                        action,
628	                        expect_utf8(p_db_name, "database name"),
629	                        expect_utf8(p_table_name, "table name"),
630	                        row_id,
631	                    );
632	                }));
633	            }
634	        }
635	
636	        let x = hook.as_ref().map(|_| call_boxed_closure::<F> as _);
637	        self.set_clientdata(c"sqlite3_update_hook", hook, |db, bh| unsafe {
638	            ffi::sqlite3_update_hook(db, x, bh);
639	            ffi::SQLITE_OK
640	        })?;
641	        Ok(())
642	    }
643	
644	    /// ```compile_fail
645	    /// use rusqlite::{Connection, Result};
646	    /// fn main() -> Result<()> {
647	    ///     let mut db = Connection::open_in_memory()?;
648	    ///     {
649	    ///         let mut called = std::sync::atomic::AtomicBool::new(false);
650	    ///         db.progress_handler(
651	    ///             1,
652	    ///             Some(|| {
653	    ///                 called.store(true, std::sync::atomic::Ordering::Relaxed);
654	    ///                 true
655	    ///             }),
656	    ///         );
657	    ///     }
658	    ///     assert!(db
659	    ///         .execute_batch("BEGIN; CREATE TABLE foo (t TEXT); COMMIT;")
660	    ///         .is_err());
661	    ///     Ok(())
662	    /// }
663	    /// ```
664	    fn progress_handler<F>(&mut self, num_ops: c_int, handler: Option<F>) -> Result<()>
665	    where
666	        F: FnMut() -> bool + Send + 'static,
667	    {
668	        unsafe extern "C" fn call_boxed_closure<F>(p_arg: *mut c_void) -> c_int
669	        where
670	            F: FnMut() -> bool,
671	        {
672	            unsafe {
673	                let r = catch_unwind(|| {
674	                    let boxed_handler: *mut F = p_arg.cast::<F>();
675	                    (*boxed_handler)()
676	                });
677	                c_int::from(r.unwrap_or_default())
678	            }
679	        }
680	
681	        let x = handler.as_ref().map(|_| call_boxed_closure::<F> as _);
682	        self.set_clientdata(c"sqlite3_progress_handler", handler, |db, bh| unsafe {
683	            ffi::sqlite3_progress_handler(db, num_ops, x, bh);
684	            ffi::SQLITE_OK
685	        })?;
686	        Ok(())
687	    }
688	
689	    /// ```compile_fail
690	    /// use rusqlite::{Connection, Result};
691	    /// fn main() -> Result<()> {
692	    ///     let mut db = Connection::open_in_memory()?;
693	    ///     {
694	    ///         let mut called = std::sync::atomic::AtomicBool::new(false);
695	    ///         db.authorizer(Some(|_: rusqlite::hooks::AuthContext<'_>| {
696	    ///             called.store(true, std::sync::atomic::Ordering::Relaxed);
697	    ///             rusqlite::hooks::Authorization::Deny
698	    ///         }));
699	    ///     }
700	    ///     assert!(db
701	    ///         .execute_batch("BEGIN; CREATE TABLE foo (t TEXT); COMMIT;")
702	    ///         .is_err());
703	    ///     Ok(())
704	    /// }
705	    /// ```
706	    fn authorizer<'c, F>(&'c mut self, authorizer: Option<F>) -> Result<()>
707	    where
708	        F: for<'r> FnMut(AuthContext<'r>) -> Authorization + Send + 'static,
709	    {
710	        unsafe extern "C" fn call_boxed_closure<'c, F>(
711	            p_arg: *mut c_void,
712	            action_code: c_int,
713	            param1: *const c_char,
714	            param2: *const c_char,
715	            db_name: *const c_char,
716	            trigger_or_view_name: *const c_char,
717	        ) -> c_int
718	        where
719	            F: FnMut(AuthContext<'c>) -> Authorization + Send + 'static,
720	        {
721	            unsafe {
722	                catch_unwind(|| {
723	                    let action = AuthAction::from_raw(
724	                        action_code,
725	                        expect_optional_utf8(param1, "authorizer param 1"),
726	                        expect_optional_utf8(param2, "authorizer param 2"),
727	                    );
728	                    let auth_ctx = AuthContext {
729	                        action,
730	                        database_name: expect_optional_utf8(db_name, "database name"),
731	                        accessor: expect_optional_utf8(
732	                            trigger_or_view_name,
733	                            "accessor (inner-most trigger or view)",
734	                        ),
735	                    };
736	                    let boxed_hook: *mut F = p_arg.cast::<F>();
737	                    (*boxed_hook)(auth_ctx)
738	                })
739	                .map_or_else(|_| ffi::SQLITE_ERROR, Authorization::into_raw)
740	            }
741	        }
742	
743	        let x_auth = authorizer
744	            .as_ref()
745	            .map(|_| call_boxed_closure::<'c, F> as _);
746	        self.set_clientdata(c"sqlite3_set_authorizer", authorizer, |db, bh| unsafe {
747	            ffi::sqlite3_set_authorizer(db, x_auth, bh)
748	        })?;
749	        Ok(())
750	    }
751	}
752	
753	unsafe fn expect_utf8<'a>(p_str: *const c_char, description: &'static str) -> &'a str {
754	    unsafe {
755	        expect_optional_utf8(p_str, description)
756	            .unwrap_or_else(|| panic!("received empty {description}"))
757	    }
758	}
759	
760	unsafe fn expect_optional_utf8<'a>(
761	    p_str: *const c_char,
762	    description: &'static str,
763	) -> Option<&'a str> {
764	    if p_str.is_null() {
765	        return None;
766	    }
767	    unsafe {
768	        CStr::from_ptr(p_str)
769	            .to_str()
770	            .unwrap_or_else(|_| panic!("received non-utf8 string as {description}"))
771	            .into()
772	    }
773	}
