484	            let _ = self.conn.execute_batch("ROLLBACK");
485	        } else {
486	            // Nested savepoint: undo only the changes made since it was
487	            // established, then release it, preserving the outer
488	            // transaction. If the rollback is not possible, do not release
489	            // either, as that would keep the changes.
490	            let _ = self.rollback().and_then(|()| self.commit_());
491	        }
492	    }
493	}
