495	fn cmd(cmd: &'static str, to: bool, name: &str) -> Result<Sql> {
496	    let mut sql = Sql::new();
497	    sql.push_keyword(cmd)?;
498	    sql.push_space();
499	    if to {
500	        sql.push_keyword("TO")?;
501	        sql.push_space();
502	    }
503	    sql.push_identifier(name);
504	    Ok(sql)
505	}
