536	impl Connection {
537	    /// Begin a new transaction with the default behavior (DEFERRED).
538	    ///
539	    /// The transaction defaults to rolling back when it is dropped. If you
540	    /// want the transaction to commit, you must call
541	    /// [`commit`](Transaction::commit) or
542	    /// [`set_drop_behavior(DropBehavior::Commit)`](Transaction::set_drop_behavior).
543	    ///
544	    /// ## Example
545	    ///
546	    /// ```rust,no_run
547	    /// # use rusqlite::{Connection, Result};
548	    /// # fn do_queries_part_1(_conn: &Connection) -> Result<()> { Ok(()) }
549	    /// # fn do_queries_part_2(_conn: &Connection) -> Result<()> { Ok(()) }
550	    /// fn perform_queries(conn: &mut Connection) -> Result<()> {
551	    ///     let tx = conn.transaction()?;
552	    ///
553	    ///     do_queries_part_1(&tx)?; // tx causes rollback if this fails
554	    ///     do_queries_part_2(&tx)?; // tx causes rollback if this fails
555	    ///
556	    ///     tx.commit()
557	    /// }
558	    /// ```
559	    ///
560	    /// # Failure
561	    ///
562	    /// Will return `Err` if the underlying SQLite call fails.
563	    #[inline]
564	    pub fn transaction(&mut self) -> Result<Transaction<'_>> {
565	        Transaction::new(self, self.transaction_behavior)
566	    }
567	
568	    /// Begin a new transaction with a specified behavior.
569	    ///
570	    /// See [`transaction`](Connection::transaction).
571	    ///
572	    /// # Failure
573	    ///
574	    /// Will return `Err` if the underlying SQLite call fails.
575	    #[inline]
576	    pub fn transaction_with_behavior(
577	        &mut self,
578	        behavior: TransactionBehavior,
579	    ) -> Result<Transaction<'_>> {
580	        Transaction::new(self, behavior)
581	    }
