583	    /// Begin a new transaction with the default behavior (DEFERRED).
584	    ///
585	    /// Attempt to open a nested transaction will result in a SQLite error.
586	    /// `Connection::transaction` prevents this at compile time by taking `&mut
587	    /// self`, but `Connection::unchecked_transaction()` may be used to defer
588	    /// the checking until runtime.
589	    ///
590	    /// See [`Connection::transaction`] and [`Transaction::new_unchecked`]
591	    /// (which can be used if the default transaction behavior is undesirable).
592	    ///
593	    /// ## Example
594	    ///
595	    /// ```rust,no_run
596	    /// # use rusqlite::{Connection, Result};
597	    /// # use std::rc::Rc;
598	    /// # fn do_queries_part_1(_conn: &Connection) -> Result<()> { Ok(()) }
599	    /// # fn do_queries_part_2(_conn: &Connection) -> Result<()> { Ok(()) }
600	    /// fn perform_queries(conn: Rc<Connection>) -> Result<()> {
601	    ///     let tx = conn.unchecked_transaction()?;
602	    ///
603	    ///     do_queries_part_1(&tx)?; // tx causes rollback if this fails
604	    ///     do_queries_part_2(&tx)?; // tx causes rollback if this fails
605	    ///
606	    ///     tx.commit()
607	    /// }
608	    /// ```
609	    ///
610	    /// # Failure
611	    ///
612	    /// Will return `Err` if the underlying SQLite call fails. The specific
613	    /// error returned if transactions are nested is currently unspecified.
614	    pub fn unchecked_transaction(&self) -> Result<Transaction<'_>> {
615	        Transaction::new_unchecked(self, self.transaction_behavior)
616	    }
