628	    /// # fn do_queries_part_1(_conn: &Connection) -> Result<()> { Ok(()) }
629	    /// # fn do_queries_part_2(_conn: &Connection) -> Result<()> { Ok(()) }
630	    /// fn perform_queries(conn: &mut Connection) -> Result<()> {
631	    ///     let sp = conn.savepoint()?;
632	    ///
633	    ///     do_queries_part_1(&sp)?; // sp causes rollback if this fails
634	    ///     do_queries_part_2(&sp)?; // sp causes rollback if this fails
635	    ///
636	    ///     sp.commit()
