    #[test]
    fn test_non_owning_hooks_cleanup() -> Result<()> {
        let mut conn = Connection::open_in_memory()?;

        static CALLED: AtomicBool = AtomicBool::new(false);
        CALLED.store(false, Ordering::Relaxed);
        conn.commit_hook(Some(|| {
